-- ---------------------------------------------------------------------
-- SOBRE LOS IDs
--
-- El esquema define «id INTEGER PRIMARY KEY», SIN autoincremento. Es decir:
-- su aplicación tiene que calcular el id de cada reserva nueva. Si lo estaban
-- haciendo con MAX(id)+1, sigue funcionando; el nuevo máximo es:
--     franjas  -> 7110
--     reservas -> 570
--
-- OPCIONAL · PostgreSQL y Supabase. Si prefieren que la base asigne el id sola,
-- descomenten estas dos líneas. Es aditivo: los INSERT que ya traen id siguen
-- funcionando igual, y los que no lo traen reciben el siguiente disponible.
--
-- ALTER TABLE reservas ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (START WITH 571);
-- ALTER TABLE franjas  ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (START WITH 7111);
--
-- OPCIONAL · MySQL y MariaDB, equivalente:
--
-- ALTER TABLE reservas MODIFY id INTEGER NOT NULL AUTO_INCREMENT, AUTO_INCREMENT = 571;
-- ALTER TABLE franjas  MODIFY id INTEGER NOT NULL AUTO_INCREMENT, AUTO_INCREMENT = 7111;
-- ---------------------------------------------------------------------
